const products = $input.all()
  .map(item => item.json)
  .filter(product => product.id != null);

return [
  {
    json: {
      found: products.length > 0,
      count: products.length,
      products: products,
      message: products.length > 0
        ? "Products found"
        : "No matching products found"
    }
  }
];
